use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        // result length equals input length
        result.len() == a.len()
    ensures
        // all elements in result are 1
        forall|i: int| (0 <= i && i < result.len()) ==> result[i as usize] == 1
{
    let len = a.len();

    // We'll specify a loop that builds a vector of length `len`
    // filled with 1s, maintaining invariants about the partial vector.

    // Loop invariant variables:
    // i: current loop index in [0..len]
    // res: the vector currently constructed
    // invariants:
    //   0 <= i <= len
    //   res.len() == i
    //   forall j in [0..i), res[j] == 1
    //
    // decreases len - i to ensure termination

    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    #[invariant(i <= len)]
    #[invariant(res.len() == i)]
    #[invariant(forall|j: int| 0 <= j && (j as usize) < i ==> res[j as usize] == 1)]
    #[decreases(len - i)]
    while i < len
    {
        res.push(1);
        i = i + 1;
    }
    ret res;
}

}